#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long MOD = 1000000007;
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        for (auto &x : a) cin >> x;
        long long total = 0, acc = 0;
        // acc: sum over earlier runs i of T(L_i) times the lengths of the runs after i so far.
        for (int i = 0; i < n;) {
            int j = i;
            while (j < n && a[j] == a[i]) j++;
            long long L = j - i, T = L * (L + 1) / 2 % MOD;
            total = (total + L * (L + 1) * (L + 2) / 6 % MOD + T * acc) % MOD;
            acc = (acc * L + T) % MOD;
            i = j;
        }
        // Subarrays with no equal neighbours are already compressed and count 0, not 1.
        long long empty = 0, streak = 1;
        for (int i = 1; i <= n; i++) {
            if (i < n && a[i] != a[i - 1]) streak++;
            else {
                empty = (empty + streak * (streak + 1) / 2) % MOD;
                streak = 1;
            }
        }
        cout << ((total - empty) % MOD + MOD) % MOD << '\n';
    }
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        final long MOD = 1_000_000_007L;
        int t = (int) nextLong();
        StringBuilder out = new StringBuilder();
        while (t-- > 0) {
            int n = (int) nextLong();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = (int) nextLong();
            long total = 0, acc = 0;
            // acc: sum over earlier runs i of T(L_i) times the lengths of the runs after i so far.
            for (int i = 0; i < n;) {
                int j = i;
                while (j < n && a[j] == a[i]) j++;
                long L = j - i, T = L * (L + 1) / 2 % MOD;
                total = (total + L * (L + 1) * (L + 2) / 6 % MOD + T * acc) % MOD;
                acc = (acc * L + T) % MOD;
                i = j;
            }
            // Subarrays with no equal neighbours are already compressed and count 0, not 1.
            long empty = 0, streak = 1;
            for (int i = 1; i <= n; i++) {
                if (i < n && a[i] != a[i - 1]) streak++;
                else {
                    empty = (empty + streak * (streak + 1) / 2) % MOD;
                    streak = 1;
                }
            }
            out.append(((total - empty) % MOD + MOD) % MOD).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	const mod = 1_000_000_007
	t := int(nextInt())
	out := []byte{}
	for ; t > 0; t-- {
		n := int(nextInt())
		a := make([]int64, n)
		for i := range a {
			a[i] = nextInt()
		}
		var total, acc int64
		// acc: sum over earlier runs i of T(L_i) times the lengths of the runs after i so far.
		for i := 0; i < n; {
			j := i
			for j < n && a[j] == a[i] {
				j++
			}
			L := int64(j - i)
			T := L * (L + 1) / 2 % mod
			total = (total + L*(L+1)*(L+2)/6%mod + T*acc) % mod
			acc = (acc*L + T) % mod
			i = j
		}
		// Subarrays with no equal neighbours are already compressed and count 0, not 1.
		var empty, streak int64 = 0, 1
		for i := 1; i <= n; i++ {
			if i < n && a[i] != a[i-1] {
				streak++
			} else {
				empty = (empty + streak*(streak+1)/2) % mod
				streak = 1
			}
		}
		out = strconv.AppendInt(out, ((total-empty)%mod+mod)%mod, 10)
		out = append(out, '\n')
	}
	os.Stdout.Write(out)
}
